using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// --- Build a chat client with automatic function-invocation ---
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelName).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Instantiate tools ---
var notebook = new Notebook();
var searcher = new WebSearcher();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(searcher.SearchAsync),
        AIFunctionFactory.Create(notebook.AddNote),
        AIFunctionFactory.Create(notebook.GetNotes),
    ]
};

// --- Read topic from the user ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Seed the conversation with a system prompt and the user request ---
List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your job is to research the given topic thoroughly.

        Follow this process:
        1. Search the web for information about the topic (make 2-3 varied searches).
        2. After each search, take notes on the key findings.
        3. Once you have enough material, review your notes and produce a final,
           comprehensive summary for the user.
        """),
    new(ChatRole.User,
        $"Please research the following topic and provide a summary: {topic}")
];

// The UseFunctionInvocation middleware runs the full tool-call loop automatically.
var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n── Research Summary ──────────────────────────");
Console.WriteLine(response.Text);
Console.WriteLine("──────────────────────────────────────────────");

// Show collected notes
var allNotes = notebook.GetNotes();
if (allNotes != "No notes yet.")
{
    Console.WriteLine("\n📝 Collected Research Notes:");
    Console.WriteLine(allNotes);
}

// ---------------------------------------------------------------------------
// Tool: Notebook – simple in-memory note-taking
// ---------------------------------------------------------------------------
partial class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Call this to record key findings.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString();
    }
}

// ---------------------------------------------------------------------------
// Tool: WebSearcher – scrapes DuckDuckGo HTML for result snippets
// ---------------------------------------------------------------------------
partial class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" }
        }
    };

    [Description("Search the web and return result snippets for the given query.")]
    public async Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var html = await Http.GetStringAsync(
                $"https://html.duckduckgo.com/html/?q={encoded}");

            var results = ParseResults(html);
            if (results.Count == 0)
                return "No results found.";

            var sb = new StringBuilder();
            sb.AppendLine($"Results for \"{query}\":\n");
            foreach (var (title, snippet, idx) in
                     results.Take(5).Select((r, i) => (r.Title, r.Snippet, i + 1)))
            {
                sb.AppendLine($"{idx}. {title}");
                if (!string.IsNullOrWhiteSpace(snippet))
                    sb.AppendLine($"   {snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    // --- Helpers ---------------------------------------------------------------

    private static List<(string Title, string Snippet)> ParseResults(string html)
    {
        var results = new List<(string, string)>();

        var titles = Regex.Matches(html,
            @"<a[^>]+class=""result__a""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        var snippets = Regex.Matches(html,
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        for (var i = 0; i < titles.Count; i++)
        {
            var title = Strip(titles[i].Groups[1].Value);
            var snippet = i < snippets.Count
                ? Strip(snippets[i].Groups[1].Value)
                : "";
            if (!string.IsNullOrWhiteSpace(title))
                results.Add((title, snippet));
        }

        return results;
    }

    private static string Strip(string raw) =>
        Regex.Replace(
            WebUtility.HtmlDecode(Regex.Replace(raw, @"<[^>]+>", " ")),
            @"\s+", " ").Trim();
}

